{
  "core_question": "What analyses must the hospital board conduct across clinical, legal, and financial domains to evaluate a private‑equity acquisition involving conversion to for‑profit status, sale‑leaseback of real estate, and a charitable foundation holding proceeds?",
  "rationale": "The transaction touches patient care standards (clinical), nonprofit tax status and regulatory approvals (legal), and valuation, financing structure, and cash flow implications (finance).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What are the key clinical considerations—including accreditation, quality metrics, community benefit obligations, and potential impacts on patient care—that the board should evaluate when a nonprofit rural hospital converts to for‑profit status under a private‑equity acquisition?",
    "legal": "What legal steps and regulatory approvals—covering IRS 501(c)(3) conversion rules, state hospital statutes, sale‑leaseback compliance, charitable foundation structuring, and any applicable antitrust or healthcare licensing requirements—must the board secure to ensure the transaction is lawful and preserves tax‑exempt benefits where appropriate?",
    "finance": "How should the board analyze the financial aspects of the proposed sale‑leaseback, including real estate valuation, lease terms, debt financing structure, impact on operating cash flow, return expectations for the private‑equity sponsor, and accounting treatment under ASC 842?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "IRS 501(c)(3) sale‑leaseback guidance, CMS reimbursement policy updates, state hospital conversion statutes, recent private equity deal structures."
}
